/*
 * psQuake -- the arena map's engine rules (engine-free, host-tested).
 *
 * New Game opens the psQuake arena (maps/psqarena.bsp, generated by
 * tools/generate_arena.py) instead of the stock start map, when the arena
 * is present. Leaving the arena resets the player's spawn parms, as a new
 * game does, so arena pickups never reach the campaign. Saving in the arena
 * is refused: process monsters carry process ids that a saved game would
 * restore after the processes are gone.
 *
 * MIT licensed, like the rest of psQuake's own files.
 */

#ifndef PSQ_ARENA_H
#define PSQ_ARENA_H

#define PSQ_ARENA_MAP  "psqarena"
#define PSQ_ARENA_BSP  "maps/" PSQ_ARENA_MAP ".bsp"
#define PSQ_START_MAP  "start"

/* 1 if mapname (the server's sv.name) names the arena, else 0: its last
 * path component is "psqarena", in any case, with or without ".bsp".
 * NULL is 0. */
int psq_arena_is_map(const char *mapname);

/* The map New Game loads: the arena when arena_present, else the stock
 * start map. */
const char *psq_new_game_map(int arena_present);

/* Which QuakeC function SV_SaveSpawnparms runs for each client before a
 * changelevel from mapname: the new-game parms when leaving the arena, the
 * usual carried-over parms otherwise. */
typedef enum
{
    PSQ_PARMS_CHANGE,  /* SetChangeParms: keep health, weapons, ammo */
    PSQ_PARMS_NEW      /* SetNewParms: start fresh */
} psq_parms_kind;

psq_parms_kind psq_changelevel_parms(const char *mapname);

/* 1 if a save must be refused on mapname. */
int psq_save_refused(const char *mapname);

#define PSQ_SAVE_REFUSED_MSG "Can't save in the psQuake arena.\n"

#endif /* PSQ_ARENA_H */
